create schema if not exists private;

create or replace function private.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create table if not exists public.stock_instruments (
  id smallint primary key check (id between 1 and 8),
  symbol text not null unique,
  display_name text not null,
  asset_class text not null,
  scenario text not null check (scenario in ('Scenario 1', 'Scenario 2')),
  source_name text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.stock_price_points (
  stock_id smallint not null
    references public.stock_instruments(id) on delete cascade,
  period smallint not null check (period between 1 and 360),
  price numeric(16, 2) not null check (price >= 0),
  updated_at timestamptz not null default now(),
  primary key (stock_id, period)
);

drop trigger if exists stock_instruments_set_updated_at
  on public.stock_instruments;
create trigger stock_instruments_set_updated_at
before update on public.stock_instruments
for each row execute function private.set_updated_at();

drop trigger if exists stock_price_points_set_updated_at
  on public.stock_price_points;
create trigger stock_price_points_set_updated_at
before update on public.stock_price_points
for each row execute function private.set_updated_at();

alter table public.stock_instruments enable row level security;
alter table public.stock_price_points enable row level security;

revoke all on table public.stock_instruments from anon, authenticated;
revoke all on table public.stock_price_points from anon, authenticated;
grant select, insert, update on table public.stock_instruments to service_role;
grant select, insert, update on table public.stock_price_points to service_role;
grant usage on schema private to service_role;
grant execute on function private.set_updated_at() to service_role;

insert into public.stock_instruments
  (id, symbol, display_name, asset_class, scenario, source_name)
values
  (1, 'BTC', 'Bitcoin', 'Digital asset', 'Scenario 1', 'BTC'),
  (2, 'KLSI', 'FTSE Bursa Malaysia KLCI', 'Market index', 'Scenario 1', 'KLSI'),
  (3, 'GOLD', 'Gold', 'Commodity', 'Scenario 1', 'GOLD'),
  (4, 'SMP500', 'S&P 500', 'Market index', 'Scenario 1', 'SMP500'),
  (5, 'BTC2', 'Bitcoin · Scenario 2', 'Digital asset', 'Scenario 2', 'BTC2'),
  (
    6,
    'KLSI2',
    'FTSE Bursa Malaysia KLCI · Scenario 2',
    'Market index',
    'Scenario 2',
    'KLSI2'
  ),
  (7, 'GOLD2', 'Gold · Scenario 2', 'Commodity', 'Scenario 2', 'GOLD2'),
  (
    8,
    'SMP5002',
    'S&P 500 · Scenario 2',
    'Market index',
    'Scenario 2',
    'SMP5002'
  )
on conflict (id) do update
set
  symbol = excluded.symbol,
  display_name = excluded.display_name,
  asset_class = excluded.asset_class,
  scenario = excluded.scenario,
  source_name = excluded.source_name;

